import React, { useState } from "react";
import { motion } from "framer-motion";
import { BRAND } from "./Content";
import { MapPin, Phone, MessageCircle } from "lucide-react";

const WhatsAppIcon = ({ size = 24 }) => (
  <svg width={size} height={size} viewBox="0 0 24 24" fill="white" xmlns="http://www.w3.org/2000/svg">
    <path d="M17.472 14.382c-.297-.149-1.758-.867-2.03-.967-.273-.099-.471-.148-.67.15-.197.297-.767.966-.94 1.164-.173.199-.347.223-.644.075-.297-.15-1.255-.463-2.39-1.475-.883-.788-1.48-1.761-1.653-2.059-.173-.297-.018-.458.13-.606.134-.133.298-.347.446-.52.149-.174.198-.298.298-.497.099-.198.05-.371-.025-.52-.075-.149-.669-1.612-.916-2.207-.242-.579-.487-.5-.669-.51-.173-.008-.371-.01-.57-.01-.198 0-.52.074-.792.372-.272.297-1.04 1.016-1.04 2.479 0 1.462 1.065 2.875 1.213 3.074.149.198 2.096 3.2 5.077 4.487.709.306 1.262.489 1.694.625.712.227 1.36.195 1.871.118.571-.085 1.758-.719 2.006-1.413.248-.694.248-1.289.173-1.413-.074-.124-.272-.198-.57-.347m-5.421 7.403h-.004a9.87 9.87 0 01-5.031-1.378l-.361-.214-3.741.982.998-3.648-.235-.374a9.86 9.86 0 01-1.51-5.26c.001-5.45 4.436-9.884 9.888-9.884 2.64 0 5.122 1.03 6.988 2.898a9.825 9.825 0 012.893 6.994c-.003 5.45-4.437 9.884-9.885 9.884m8.413-18.297A11.815 11.815 0 0012.05 0C5.495 0 .16 5.335.157 11.892c0 2.096.547 4.142 1.588 5.945L.057 24l6.305-1.654a11.882 11.882 0 005.683 1.448h.005c6.554 0 11.89-5.335 11.893-11.893a11.821 11.821 0 00-3.48-8.413z"/>
  </svg>
);

export default function Contact() {
  const [formData, setFormData] = useState({ name: "", phone: "", eventType: "", message: "" });

  const handleSubmit = (e) => {
    e.preventDefault();
    const text = `*New Inquiry - D SAJAWAT Website*\n\n*Name:* ${formData.name}\n*Phone:* ${formData.phone}\n*Event Type:* ${formData.eventType}\n*Message:* ${formData.message}`;
    window.open(`https://wa.me/${BRAND.whatsapp[0]}?text=${encodeURIComponent(text)}`, "_blank");
  };

  return (
    <section id="contact" className="section" style={{ background: "#fdf8ed" }}>
      <div className="container mx-auto">
        <motion.div className="mb-12 lg:mb-16 text-center" initial={{ opacity: 0, y: 20 }} whileInView={{ opacity: 1, y: 0 }} viewport={{ once: true }} transition={{ duration: 0.6 }}>
          <div className="flex items-center justify-center gap-3 mb-6">
            <div className="w-10 h-px" style={{ background: "linear-gradient(90deg, transparent, #d4af37)" }} />
            <span className="section-overline">Get In Touch</span>
            <div className="w-10 h-px" style={{ background: "linear-gradient(90deg, #d4af37, transparent)" }} />
          </div>
          <h2 className="section-title">Let&apos;s decorate your <span>event</span></h2>
          <p className="section-subtitle mt-6 mx-auto text-center">Whether you need a single table cover or bulk supplies - we deliver Pan India with the same care every time.</p>
        </motion.div>

        <div className="contact-grid">
          <motion.div initial={{ opacity: 0, x: -30 }} whileInView={{ opacity: 1, x: 0 }} viewport={{ once: true }} transition={{ duration: 0.7 }}>
            <div className="card mb-5 flex items-center gap-4 lg:gap-5">
              <div className="w-12 h-12 lg:w-14 lg:h-14 rounded-full flex items-center justify-center flex-shrink-0" style={{ background: "rgba(212,175,55,0.15)" }}><MapPin size={22} color="#d4af37" /></div>
              <div><span className="section-overline block mb-1">Location</span><span className="font-medium text-base lg:text-lg" style={{ color: "#1a080a" }}>{BRAND.location}</span></div>
            </div>
            <div className="card mb-5 flex items-center gap-4 lg:gap-5">
              <div className="w-12 h-12 lg:w-14 lg:h-14 rounded-full flex items-center justify-center flex-shrink-0" style={{ background: "rgba(212,175,55,0.15)" }}><Phone size={22} color="#d4af37" /></div>
              <div><span className="section-overline block mb-1">Phone</span><div className="flex flex-col sm:flex-row sm:gap-4 lg:gap-6"><a href={`tel:${BRAND.phones[0]}`} className="font-medium text-base lg:text-lg hover:text-[#d4af37]" style={{ color: "#1a080a" }}>{BRAND.phones[0]}</a><a href={`tel:${BRAND.phones[1]}`} className="font-medium text-base lg:text-lg hover:text-[#d4af37]" style={{ color: "#1a080a" }}>{BRAND.phones[1]}</a></div></div>
            </div>
            <motion.a href={`https://wa.me/${BRAND.whatsapp[0]}?text=Hi! I visited your website and would like to inquire about D SAJAWAT fabrics.`} target="_blank" rel="noopener noreferrer" className="btn-primary w-full flex items-center justify-center gap-3" style={{ background: "linear-gradient(135deg, #25d366 0%, #128c7e 100%)", boxShadow: "0 4px 20px rgba(37, 211, 102, 0.3)" }} whileHover={{ scale: 1.02 }} whileTap={{ scale: 0.98 }}>
              <WhatsAppIcon size={20} /><span>Chat on WhatsApp</span>
            </motion.a>
          </motion.div>

          <motion.div initial={{ opacity: 0, x: 30 }} whileInView={{ opacity: 1, x: 0 }} viewport={{ once: true }} transition={{ duration: 0.7, delay: 0.2 }}>
            <div className="card">
              <h3 className="serif mb-6 lg:mb-8" style={{ fontSize: "clamp(22px, 3vw, 28px)", color: "#1a080a" }}>Send us a message</h3>
              <form onSubmit={handleSubmit} className="space-y-4 lg:space-y-5">
                <div className="grid grid-cols-1 sm:grid-cols-2 gap-4 lg:gap-5">
                  <div><label className="section-overline block mb-2">Your Name *</label><input type="text" required className="field" placeholder="Enter your name" value={formData.name} onChange={(e) => setFormData({ ...formData, name: e.target.value })} /></div>
                  <div><label className="section-overline block mb-2">Phone *</label><input type="tel" required className="field" placeholder="Your phone number" value={formData.phone} onChange={(e) => setFormData({ ...formData, phone: e.target.value })} /></div>
                </div>
                <div><label className="section-overline block mb-2">Event Type</label><select className="field" value={formData.eventType} onChange={(e) => setFormData({ ...formData, eventType: e.target.value })}><option value="">Select event type</option><option value="Wedding">Wedding</option><option value="Corporate Event">Corporate Event</option><option value="Birthday Party">Birthday Party</option><option value="Festival">Festival</option><option value="Other">Other</option></select></div>
                <div><label className="section-overline block mb-2">Your Message</label><textarea className="field" rows={4} placeholder="Tell us about your requirements..." value={formData.message} onChange={(e) => setFormData({ ...formData, message: e.target.value })} style={{ resize: "vertical", minHeight: 100 }} /></div>
                <button type="submit" className="btn-primary w-full"><MessageCircle size={18} /><span>Send via WhatsApp</span></button>
              </form>
            </div>
          </motion.div>
        </div>
      </div>
    </section>
  );
}
